import "server-only";
import fs from "node:fs";
import path from "node:path";
import { kindSlug } from "./nav";

/** Generated by `make crd-docs` in go/operator from the API types. */
const API_FILE = path.join(process.cwd(), "..", "documentation", "operator", "api.json");

export type CelRule = { rule: string; message: string };

export type OperatorField = {
  name: string;
  /** Markdown: local types link to `#<anchor>`, known Kubernetes types to their docs. */
  type: string;
  doc: string;
  default: string;
  validation: string[];
  rules: CelRule[];
};

export type OperatorType = {
  name: string;
  /** Set for resource kinds. */
  kind: string;
  resource: { scope?: string; shortNames?: string[] };
  doc: string;
  /** Markdown type of an alias, e.g. `string` for an enum. */
  underlying: string;
  validation: string[];
  rules: CelRule[];
  fields: OperatorField[];
  appearsIn: string[];
  enumValues: { name: string; doc: string }[];
};

export type OperatorKind = {
  kind: string;
  slug: string;
  summary: string;
  scope: string;
  shortNames: string[];
  /** The kind first, then every type it reaches, breadth first. */
  types: OperatorType[];
};

export type OperatorApi = {
  groupVersion: string;
  kinds: OperatorKind[];
  /** Kind pages documenting each type, by type name. */
  pagesFor: Record<string, string[]>;
};

type RawApi = {
  groupVersions: { groupVersion: string; doc: string; kinds: string[]; types: OperatorType[] }[];
};

/** The anchor crd-ref-docs links a local type to. */
export function typeAnchor(name: string): string {
  return name.toLowerCase().replace(/[ ./()]/g, "");
}

const LOCAL_LINK = /\]\(#([^)]+)\)/g;

function referenced(type: OperatorType): string[] {
  const sources = [type.underlying, ...type.fields.map((f) => f.type)];
  return sources.flatMap((s) => Array.from(s.matchAll(LOCAL_LINK), (m) => m[1]));
}

/** First paragraph of a Go doc comment, on one line. */
export function firstParagraph(doc: string): string {
  return (doc.split(/\n\s*\n/)[0] ?? "").replace(/\s*\n\s*/g, " ").trim();
}

let cached: OperatorApi | undefined;

export function loadOperatorApi(): OperatorApi {
  if (cached) return cached;
  const raw = JSON.parse(fs.readFileSync(API_FILE, "utf8")) as RawApi;
  if (raw.groupVersions.length !== 1) throw new Error(`${API_FILE}: expected one API group version`);
  const [gv] = raw.groupVersions;
  const byAnchor = new Map(gv.types.map((t) => [typeAnchor(t.name), t]));
  // crd-ref-docs copies a type's markers onto the fields of that type; list its rules once, on the type.
  for (const type of gv.types) {
    for (const field of type.fields) {
      const inherited = new Set(
        Array.from(field.type.matchAll(LOCAL_LINK), (m) => byAnchor.get(m[1])?.rules ?? []).flat().map((r) => r.rule),
      );
      field.rules = field.rules.filter((r) => !inherited.has(r.rule));
    }
  }

  const kinds = gv.kinds.map((kind): OperatorKind => {
    const root = byAnchor.get(typeAnchor(kind));
    if (!root) throw new Error(`${API_FILE}: kind ${kind} has no type`);
    const types: OperatorType[] = [];
    const seen = new Set<string>();
    const queue = [root];
    while (queue.length) {
      const type = queue.shift()!;
      if (seen.has(type.name)) continue;
      seen.add(type.name);
      types.push(type);
      for (const anchor of referenced(type)) {
        const next = byAnchor.get(anchor);
        if (next && !seen.has(next.name)) queue.push(next);
      }
    }
    const spec = types.find((t) => t.name === `${kind}Spec`);
    return {
      kind,
      slug: kindSlug(kind),
      summary: firstParagraph(root.doc) || firstParagraph(spec?.doc ?? ""),
      scope: root.resource.scope ?? "Namespaced",
      shortNames: root.resource.shortNames ?? [],
      types,
    };
  });

  const pagesFor: Record<string, string[]> = {};
  for (const k of kinds) for (const t of k.types) (pagesFor[t.name] ??= []).push(k.kind);

  cached = { groupVersion: gv.groupVersion, kinds, pagesFor };
  return cached;
}
